    },
    {
      "name": "Finset.weightedVSub_const_smul",
      "module_name": "Mathlib.LinearAlgebra.AffineSpace.Combination",
      "kind": "theorem",
      "type": "∀ {k : Type u_1} {V : Type u_2} {P : Type u_3} [inst : Ring k] [inst_1 : AddCommGroup V] [inst_2 : Module k V]\n  [S : AddTorsor V P] {ι : Type u_4} (s : Finset ι) (w : ι → k) (p : ι → P) (c : k),\n  (s.weightedVSub p) (c • w) = c • (s.weightedVSub p) w"
    },
    {
      "name": "Finset.sum_smul_const_vsub_eq_sub_weightedVSubOfPoint",
      "module_name": "Mathlib.LinearAlgebra.AffineSpace.Combination",
      "kind": "theorem",
      "type": "∀ {k : Type u_1} {V : Type u_2} {P : Type u_3} [inst : Ring k] [inst_1 : AddCommGroup V] [inst_2 : Module k V]\n  [S : AddTorsor V P] {ι : Type u_4} (s : Finset ι) (w : ι → k) (p₂ : ι → P) (p₁ b : P),\n  ∑ i ∈ s, w i • (p₁ -ᵥ p₂ i) = (∑ i ∈ s, w i) • (p₁ -ᵥ b) - (s.weightedVSubOfPoint p₂ b) w"
    },
    {
      "name": "Finset.centerMass_eq_of_sum_1",
      "module_name": "Mathlib.Analysis.Convex.Combination",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {E : Type u_3} {ι : Type u_5} [inst : Field R] [inst_1 : AddCommGroup E] [inst_2 : Module R E]\n  (t : Finset ι) {w : ι → R} (z : ι → E), ∑ i ∈ t, w i = 1 → t.centerMass w z = ∑ i ∈ t, w i • z i"
    }
